// ARCH-001.a, ARCH-004 | 2026-11-10 | One generated catalog keeps serialized references to
// imported assets and daily records so builds include them without path lookups.
// Decision: .agents/architecture/ARCH-001.a-content-registry.md
// Journal: .agents/days/2026-11-12.md
using System;
using System.Collections.Generic;
using UnityEngine;

namespace TomorrowAtEight.Content
{
    /// <summary>
    /// Generated by the editor command TomorrowAtEight/Run/Rebuild Imported Asset Catalog.
    /// Do not edit by hand; the editor import map is the source of its bindings.
    /// </summary>
    public sealed class ImportedAssetCatalog : ScriptableObject, IImportedAssetSource
    {
        /// <summary>Fixed Resources entry point used by the bootstrap.</summary>
        public const string ResourcesPath = "TomorrowAtEight/ImportedAssets";

        [Serializable]
        public struct Entry
        {
            public string key;
            public UnityEngine.Object asset;
        }

        public List<Entry> entries = new List<Entry>();

        /// <summary>Public daily JSON records included in this build (ARCH-004).</summary>
        public List<TextAsset> dailyRecords = new List<TextAsset>();

        public bool TryGetAsset(string contentId, out UnityEngine.Object asset)
        {
            for (int i = 0; i < entries.Count; i++)
            {
                if (string.Equals(entries[i].key, contentId, StringComparison.Ordinal))
                {
                    asset = entries[i].asset;
                    return asset != null;
                }
            }
            asset = null;
            return false;
        }

        public static ImportedAssetCatalog Load()
        {
            return Resources.Load<ImportedAssetCatalog>(ResourcesPath);
        }
    }
}
